    def candidate(coord):
        bands = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == 0:
                    continue
                k = coord(r, c)
                if k in bands and bands[k] != color:
                    return None
                bands[k] = color
        if not bands:
            return None
        # Choose the smallest periodic diagonal palette that explains every
        # observed stripe and has a known color for each residue.
        for period in range(1, max(h, w) * 2 + 1):
            palette = {}
            valid = True
            for k, color in bands.items():
                residue = k % period
                if residue in palette and palette[residue] != color:
                    valid = False
                    break
                palette[residue] = color
            if valid and len(palette) == period:
                return period, palette
        return None

    diagonal = candidate(lambda r, c: c - r)
    antidiagonal = candidate(lambda r, c: r + c)
    if diagonal is None and antidiagonal is None:
        return [row[:] for row in grid]
    if diagonal is None:
        coord, result = (lambda r, c: r + c), antidiagonal
    elif antidiagonal is None:
        coord, result = (lambda r, c: c - r), diagonal
    else:
        # Prefer the orientation with fewer stripe colors/shorter period;
        # ties prefer the orientation with more observed complete bands.
        p1, pal1 = diagonal
        p2, pal2 = antidiagonal
        if p1 <= p2:
            coord, result = (lambda r, c: c - r), diagonal
        else:
            coord, result = (lambda r, c: r + c), antidiagonal

    period, palette = result
    return [[palette[coord(r, c) % period] for c in range(w)] for r in range(h)]


